command:example.dev:code:
New-OfficeExcel -Path .\Reports\Regions.xlsx {
                ExcelSheet 'Summary' {
                    ExcelTable (Import-OfficeCsv -Path .\Data\Region-Revenue.csv) -Name RegionSummary
                    ExcelChart -Table RegionSummary -Category Region -Value Revenue -Address F2 -Type Column -Title 'Revenue by region'
                }
            }

$trend = Import-OfficeCsv -Path .\Data\Ticket-Trend.csv
            New-OfficeExcel -Path .\Reports\Helpdesk-Trend.xlsx {
                ExcelSheet 'Trend' {
                    ExcelChart -InputObject $trend -Category Week -Value Opened, Closed -Type Line -Address A1 -Title 'Tickets per week' -Width 18cm -Height 9cm
                }
            }

Open-OfficeExcel -Path .\Finance\Budget-2027.xlsx {
                ExcelSheet 'Summary' {
                    ExcelChart B3:C15 -Address E3 -Type Bar -Title 'Budget by month'
                }
            }

Open-OfficeExcel -Path .\Finance\Budget-2027.xlsx {
                ExcelSheet 'Assumptions' {
                    ExcelComment B4 'Inflation from the October central bank projection.' -Author 'Finance'
                }
            }

Open-OfficeExcel -Path .\Finance\Forecast-2027.xlsx {
                ExcelSheet 'Forecast' {
                    ExcelComment F12 'Can we confirm the Q2 hiring plan before this goes to the board?' -Threaded -Author 'Anna Kowalska'
                }
            }

Open-OfficeExcel -Path .\Reports\Q3-Performance.xlsx {
                ExcelSheet 'Performance' {
                    ExcelConditionalFormat -Header Attainment -Table Actuals -StartColor Danger -MidColor Warning -EndColor Success
                    ExcelConditionalFormat -Header Change -Table Actuals -IconSet ThreeArrows
                }
            }

Open-OfficeExcel -Path .\Reports\Q3-Sales.xlsx {
                ExcelSheet 'Orders' {
                    ExcelConditionalFormat E2:E500 -Rule CellIs -Operator LessThan -Value 0 -BackgroundColor '#FEE2E2' -Color Danger
                }
            }

Open-OfficeExcel -Path .\Reports\Users.xlsx {
                ExcelSheet 'Users' {
                    ExcelConditionalFormat -Header LastLogon -Table Users -Rule CellIs -Operator LessThan -Value '=TODAY()-90' -BackgroundColor Danger
                }
            }

Open-OfficeExcel -Path .\Reports\Sales-2026.xlsx {
                ExcelConnection -Name SalesQuery -CommandText 'let Source = Excel.CurrentWorkbook(){[Name="Orders"]}[Content] in Source'
            }

$query = 'let Source = Sql.Database("dw.example.com", "Sales"), Orders = Source{[Schema="dbo", Item="Orders"]}[Data] in Orders'
            Open-OfficeExcel -Path .\Reports\Live-Sales.xlsx {
                ExcelConnection -Sheet Data -Name WarehouseOrders -CommandText $query -Description 'Orders from the sales warehouse' -QueryTable OrdersQuery -RefreshOnOpen
            }

New-OfficeExcel -Path .\Reports\Q3-Sales.xlsx {
                ExcelSheet 'Cover' {
                    ExcelImage .\Assets\Logo.png -Address A1 -AltText 'Northwind Traders logo'
                }
            }

Open-OfficeExcel -Path .\Facilities\Inspection-Gdansk.xlsx {
                ExcelSheet 'Findings' {
                    ExcelImage .\Photos\Gdansk-Roof-0412.jpg -Address D2:J20 -Placement MoveAndSize -AltText 'Roof drainage at the Gdansk warehouse'
                }
            }

$sites = Import-OfficeExcel -Path .\Reports\Inventory.xlsx -Sheet Servers
            $firstRows = @()
            $rowNumber = 2
            foreach ($group in $sites | Group-Object Site) {
                if ($rowNumber -gt 2) { $firstRows += $rowNumber }
                $rowNumber += $group.Count
            }
            Open-OfficeExcel -Path .\Reports\Inventory.xlsx {
                ExcelSheet 'Servers' {
                    ExcelPageBreak -Row $firstRows
                }
            }

Open-OfficeExcel -Path .\Reports\Q3-Sales.xlsx {
                ExcelSheet 'Orders' {
                    ExcelPivotTable -Range A1:F500 -Address H2 -RowField Region -DataField Amount -DataFunction Sum
                }
            }

$orders = Import-OfficeCsv -Path .\Data\Orders-2026.csv
            New-OfficeExcel -Path .\Reports\Sales-2026.xlsx {
                ExcelSheet 'Orders' {
                    ExcelTable $orders -Name Orders
                    ExcelPivotTable -Table Orders -Address J3 -Name SalesPivot -RowField Region -ColumnField Quarter -PageField Product -DataField Amount -DataFunction Sum -DataDisplayName 'Revenue' -DataNumberFormat '#,##0' -Layout Tabular -RefreshOnOpen
                }
            }

Open-OfficeExcel -Path .\Reports\Q3-Sales.xlsx {
                ExcelSheet 'Summary' {
                    ExcelPivotTable -SourceSheet Orders -Address A3 -RowField Region -ColumnField Product -DataField Amount -DataFunction Sum
                }
            }

New-OfficeExcel -Path .\Reports\Operations.xlsx {
                ExcelReportSheet 'Summary' {
                    ExcelReportCallout Info 'Data source' 'Monitoring export from 1 November, 06:00.'
                }
            }

$failed = Import-OfficeCsv -Path .\Data\Backup-Results.csv | Where-Object Result -ne 'Success'
            New-OfficeExcel -Path .\Reports\Backup-Check.xlsx {
                ExcelReportSheet 'Backups' {
                    ExcelReportTitle 'Nightly backup check' (Get-Date).ToString('d MMMM yyyy')
                    if ($failed) {
                        ExcelReportCallout Error 'Backups failed' "$(@($failed).Count) jobs did not complete. Details are below."
                        ExcelReportTable $failed 'Failed jobs'
                    } else {
                        ExcelReportCallout Success 'All backups completed' 'Every scheduled job finished successfully.'
                    }
                }
            }

New-OfficeExcel -Path .\Reports\Regions.xlsx {
                ExcelReportSheet 'Summary' {
                    ExcelReportTable (Import-OfficeCsv -Path .\Data\Region-Revenue.csv) 'Revenue by region'
                    ExcelReportChart -Category Region -Value Revenue
                }
            }

New-OfficeExcel -Path .\Reports\Helpdesk-Review.xlsx {
                ExcelReportSheet 'Trend' {
                    ExcelReportTitle 'Helpdesk trend' 'Last 12 weeks'
                    ExcelReportTable (Import-OfficeCsv -Path .\Data\Ticket-Trend.csv) 'Tickets per week'
                    ExcelReportChart -Preset Trend -Category Week -Value Opened, Closed -Title 'Opened and closed tickets'
                }
            }

New-OfficeExcel -Path .\Reports\Security-Review.xlsx {
                ExcelReportSheet 'Review' {
                    ExcelReportTitle 'Security review' 'Q3 2026'
                    ExcelReportHeading 'Privileged accounts'
                    ExcelReportTable (Import-OfficeCsv -Path .\Data\Privileged-Accounts.csv)
                    ExcelReportHeading 'Firewall changes'
                    ExcelReportTable (Import-OfficeCsv -Path .\Data\Firewall-Changes.csv)
                }
            }

New-OfficeExcel -Path .\Reports\Operations.xlsx {
                ExcelReportSheet 'Summary' {
                    ExcelReportKpi ([ordered]@{ Uptime = '99.97%'; Incidents = 4; Deployments = 37 })
                }
            }

$orders = Import-OfficeCsv -Path .\Data\Q3-Orders.csv
            $kpis = [ordered]@{
                Revenue           = ($orders | Measure-Object Amount -Sum).Sum
                Orders            = $orders.Count
                'Average order'   = [math]::Round(($orders | Measure-Object Amount -Average).Average, 2)
                'Active customers' = ($orders | Select-Object -ExpandProperty Customer -Unique).Count
            }
            New-OfficeExcel -Path .\Reports\Q3-Sales-Summary.xlsx {
                ExcelReportSheet 'Summary' {
                    ExcelReportTitle 'Q3 sales' 'July to September 2026'
                    ExcelReportKpi $kpis -PerRow 4
                }
            }

$legend = @(
                [pscustomobject]@{ Status = 'Ready'; Meaning = 'Validated and ready to ship' }
                [pscustomobject]@{ Status = 'Review'; Meaning = 'Waiting for the owner' }
            )
            New-OfficeExcel -Path .\Reports\Release-Readiness.xlsx {
                ExcelReportSheet 'Readiness' {
                    ExcelReportLegend 'Status' -Header Status, Meaning -InputObject $legend
                }
            }

$legend = @(
                [pscustomobject]@{ Status = 'Ready'; Meaning = 'Validated and ready to ship' }
                [pscustomobject]@{ Status = 'Review'; Meaning = 'Waiting for the owner' }
                [pscustomobject]@{ Status = 'Blocked'; Meaning = 'Cannot ship until a dependency is fixed' }
            )
            New-OfficeExcel -Path .\Reports\Release-Readiness.xlsx {
                ExcelReportSheet 'Readiness' {
                    ExcelReportTable (Import-OfficeCsv -Path .\Data\Release-Items.csv) 'Release 2026.11'
                    ExcelReportLegend 'Status' -Header Status, Meaning -InputObject $legend -FirstColumnFillByValue @{ Ready = '#DCFCE7'; Review = '#FEF3C7'; Blocked = '#FEE2E2' }
                }
            }

New-OfficeExcel -Path .\Reports\Operations.xlsx {
                ExcelReportSheet 'Summary' {
                    ExcelReportParagraph 'Figures cover all production services from 1 to 31 October.'
                }
            }

New-OfficeExcel -Path .\Reports\Service-Review-October.xlsx {
                ExcelReportSheet 'Review' {
                    ExcelReportHeading 'Availability by site'
                    ExcelReportParagraph 'Availability is measured every minute from two external probes. Planned maintenance announced five days ahead is excluded.'
                    ExcelReportTable (Import-OfficeCsv -Path .\Data\Site-Availability.csv)
                }
            }

New-OfficeExcel -Path .\Reports\Operations.xlsx {
                ExcelReportSheet 'Summary' {
                    ExcelReportTitle 'Operations summary' 'Week 43, 2026'
                    ExcelReportKpi ([ordered]@{ Uptime = '99.97%'; Incidents = 4; 'Changes shipped' = 37 })
                }
            }

$sites = Import-OfficeCsv -Path .\Data\Site-Availability.csv
            $legend = @(
                [pscustomobject]@{ Status = 'Met'; Meaning = 'Availability at or above the 99.9% target' }
                [pscustomobject]@{ Status = 'Missed'; Meaning = 'Below target; a service credit may apply' }
            )
            New-OfficeExcel -Path .\Reports\Service-Review-October.xlsx -Theme Boardroom {
                ExcelReportSheet 'Review' {
                    ExcelReportTitle 'Service review' 'October 2026'
                    ExcelReportKpi ([ordered]@{ Availability = '99.94%'; 'P1 incidents' = 1; 'Mean time to restore' = '42 min'; 'Changes' = 128 })
                    ExcelReportCallout Warning 'Two sites missed target' 'Gdansk and Porto were below 99.9% after the network maintenance on 14 October.'
                    ExcelReportHeading 'Availability by site'
                    ExcelReportTable $sites 'Sites'
                    ExcelReportChart -Type Column -Category Site -Value Availability -Title 'Availability by site'
                    ExcelReportSpacer
                    ExcelReportLegend 'Status' -Header Status, Meaning -InputObject $legend
                }
            }

New-OfficeExcel -Path .\Reports\Operations.xlsx {
                ExcelReportSheet 'Summary' {
                    ExcelReportTitle 'Operations summary'
                    ExcelReportSpacer
                    ExcelReportParagraph 'Week 43, 2026'
                }
            }

New-OfficeExcel -Path .\Reports\Helpdesk-Review.xlsx {
                ExcelReportSheet 'Review' {
                    ExcelReportKpi ([ordered]@{ Opened = 412; Closed = 398; 'Median age' = '1.6 days' })
                    ExcelReportSpacer 2
                    ExcelReportTable (Import-OfficeCsv -Path .\Data\Tickets-By-Team.csv) 'Tickets by team'
                }
            }

New-OfficeExcel -Path .\Reports\Operations.xlsx {
                ExcelReportSheet 'Summary' {
                    ExcelReportTable (Get-Service | Where-Object Status -eq 'Stopped') 'Stopped services'
                }
            }

$assets = Import-OfficeCsv -Path .\Data\Assets.csv
            New-OfficeExcel -Path .\Reports\Asset-Review.xlsx {
                ExcelReportSheet 'Assets' {
                    ExcelReportTitle 'Laptops due for replacement'
                    ExcelReportTable ($assets | Where-Object AgeYears -ge 4) 'Due this year' -Property AssetTag, User, Model, Purchased, AgeYears -Name DueLaptops -ColumnFormat @{ Purchased = 'Date'; AgeYears = '0.0' }
                }
            }

$period = (Get-Date).ToString('MMMM yyyy')
            New-OfficeExcel -Path .\Reports\Capacity-Review.xlsx {
                ExcelReportSheet 'Capacity' {
                    ExcelReportTitle 'Capacity review' "Storage and compute, $period"
                    ExcelReportTable (Import-OfficeCsv -Path .\Data\Capacity.csv) 'Clusters'
                }
            }

$staff = Import-OfficeCsv -Path .\HR\Headcount-2026-10.csv
            New-OfficeExcel -Path .\Reports\Headcount.xlsx {
                foreach ($group in $staff | Group-Object Department) {
                    ExcelSheet $group.Name -ValidationMode Sanitize {
                        ExcelTable ($group.Group | Select-Object Name, Title, Location, StartDate)
                    }
                }
            }

New-OfficeExcel -Path .\Reports\Site-Incidents.xlsx {
                ExcelSheet 'Incidents' {
                    ExcelTable (Import-OfficeCsv -Path .\Data\Incidents-By-Week.csv) -Name Incidents
                    ExcelSparkline -DataRange B2:M9 -LocationRange N2:N9 -Type Column -ShowHighLow
                }
            }

Open-OfficeExcel -Path .\Finance\Expenses-October.xlsx {
                ExcelSheet 'Expenses' {
                    ExcelSort CostCentre
                    ExcelSubtotal -GroupColumn CostCentre -ValueColumn Amount, Vat -Function Sum -GrandTotalLabel 'All cost centres' -HideDetailRows
                }
            }

$targets = Import-OfficeCsv -Path .\Data\Q3-Targets.csv
            $actuals = Import-OfficeCsv -Path .\Data\Q3-Actuals.csv
            New-OfficeExcel -Path .\Reports\Q3-Performance.xlsx {
                ExcelSheet 'Performance' {
                    ExcelTable $targets -Name Targets -Address A1
                    ExcelTable $actuals -Name Actuals -Address G1 -ColumnFormat @{ Attainment = 'Percent' }
                }
            }

$orders = Import-OfficeCsv -Path .\Data\Q3-Orders.csv
            New-OfficeExcel -Path .\Reports\Q3-Regions.xlsx {
                foreach ($group in $orders | Group-Object Region) {
                    ExcelSheet $group.Name {
                        ExcelTable $group.Group -Address A3
                    }
                }
                ExcelTableOfContents -Name 'Contents' -BackLink -BackLinkAddress A1 -BackLinkText 'Back to contents'
            }

$servers = @(
                [pscustomobject]@{ Name = 'NW-APP-07'; Role = 'Application'; Site = 'Warsaw' }
                [pscustomobject]@{ Name = 'NW-SQL-03'; Role = 'Database'; Site = 'Frankfurt' }
            )
            Open-OfficeExcel -Path .\Reports\Inventory.xlsx {
                Add-OfficeExcelTableRow -Sheet Servers -Table Servers -InputObject $servers
            }

$book = Open-OfficeExcel -Path .\Reports\Deployments.xlsx
            foreach ($target in 'NW-APP-01', 'NW-APP-02', 'NW-APP-03') {
                $result = Invoke-Command -ComputerName $target { & C:\Deploy\Install.ps1 -Release '2026.10.2' }
                [pscustomobject]@{ Server = $target; Release = '2026.10.2'; Finished = Get-Date; Status = $result.Status } |
                    Add-OfficeExcelTableRow -Document $book -Sheet Log -Table Deployments
            }
            Save-OfficeExcel -Document $book -PassThru | Close-OfficeExcel

New-OfficeExcel -Path .\Status.xlsx {
                ExcelSheet 'Summary' {
                    ExcelCell A1 {
                        ExcelText 'Owner: ' -Bold
                        ExcelText 'Infrastructure team'
                    }
                }
            }

Open-OfficeExcel -Path .\Reports\Migration.xlsx {
                ExcelSheet 'Overview' {
                    ExcelCell B3 {
                        ExcelText 'Cutover risk: '
                        ExcelText 'High' -Bold -Color Danger -Size 12pt
                        ExcelText '1' -VerticalAlignment Superscript
                    }
                    ExcelCell B20 '1 Vendor patch not yet certified for production.'
                }
            }

Open-OfficeExcel -Path .\Reports\Helpdesk.xlsx {
                ExcelSheet 'Tickets' {
                    ExcelValidation -Range C2:C500 -Type List -Values 'Open', 'In progress', 'On hold', 'Closed'
                }
            }

Open-OfficeExcel -Path .\Forms\Equipment-Requests.xlsx {
                ExcelSheet 'Requests' {
                    ExcelValidation -Header Quantity -Table Requests -Type WholeNumber -Operator Between -Value 1 -SecondValue 500 -NoBlank -ErrorTitle 'Quantity' -ErrorMessage 'Enter a whole number from 1 to 500.'
                }
            }

Open-OfficeExcel -Path .\Projects\Plan.xlsx {
                ExcelSheet 'Tasks' {
                    ExcelValidation -Range D2:D300 -Type Formula -Formula '=D2>=C2' -ErrorMessage 'The end date must be on or after the start date.'
                }
            }

New-OfficeMarkdown -Path .\ReleaseNotes.md {
                Add-OfficeMarkdownHeading -Level 1 -Text 'Release notes'
                Add-OfficeMarkdownCallout -Kind 'note' -Title 'Validation' -Text 'Artifacts were generated from deterministic example data.'
                Add-OfficeMarkdownCallout -Kind 'warning' -Title 'Manual step' -Text 'Open the workbook in desktop Excel before publishing pivots.'
            }

New-OfficeMarkdown -Path .\Report.md {
                Add-OfficeMarkdownHeading -Level 1 -Text 'Operational Report'
                Add-OfficeMarkdownTableOfContents -Title 'Contents' -MinLevel 2 -MaxLevel 3 -PlaceAtTop
                Add-OfficeMarkdownHeading -Level 2 -Text 'Overview'
                Add-OfficeMarkdownParagraph -Text 'Current operational state.'
            }

New-OfficeMarkdown -Path .\Report.md {
                Add-OfficeMarkdownHeading -Level 2 -Text 'Summary'
                Add-OfficeMarkdownParagraph -Text 'Key decisions and status.'
                Add-OfficeMarkdownHorizontalRule
                Add-OfficeMarkdownHeading -Level 2 -Text 'Appendix'
            }

New-OfficeMarkdown -Path .\Plan.md {
                Add-OfficeMarkdownHeading -Level 2 -Text 'Priorities'
                Add-OfficeMarkdownList -Items 'PDF examples', 'PowerPoint layout', 'Word report polish'
                Add-OfficeMarkdownHeading -Level 2 -Text 'Release order'
                Add-OfficeMarkdownList -Items 'Validate artifacts', 'Generate docs', 'Publish release' -Numbered -Start 1
            }

New-OfficeMarkdown -Path .\Report.md {
                Add-OfficeMarkdownHeading -Level 1 -Text 'Operational Report'
                Add-OfficeMarkdownParagraph -Text 'This report is generated automatically from validated source data.'
                Add-OfficeMarkdownParagraph -Text 'Use the linked artifacts for workbook, PDF, and presentation proof.'
            }

New-OfficeMarkdown -Path .\ExecutiveSummary.md {
                Add-OfficeMarkdownHeading -Level 1 -Text 'Executive summary'
                Add-OfficeMarkdownQuote -Text 'The release is ready when examples, generated docs, and artifact readback all agree.'
                Add-OfficeMarkdownParagraph -Text 'Detailed validation follows.'
            }

New-OfficeMarkdown -Path .\ReleaseChecklist.md {
                Add-OfficeMarkdownHeading -Level 1 -Text 'Release checklist'
                Add-OfficeMarkdownTaskList -Items 'Generate examples', 'Refresh docs', 'Validate artifacts', 'Publish release' -Completed 0, 1
            }

$dataPath = '.\Examples\Documents\ServiceData.json'
            Set-Content -Path $dataPath -Value '{ "service": "Directory", "status": "Healthy" }'
            New-OfficePdf -Path .\Examples\Documents\PdfWithAttachment.pdf {
                Add-OfficePdfHeading -Text 'Service report'
                Add-OfficePdfAttachment -Path $dataPath -Name 'service-data.json' -MimeType 'application/json' -Description 'Source data used by the report.'
            }

New-OfficePdf -Path .\Report.pdf {
                PdfBackgroundShape -Shape TopBand -Height 86 -FillColor '#DBEAFE' -FillOpacity 0.75
                PdfBackgroundShape -Shape Ellipse -X 420 -Y 650 -Width 96 -Height 72 -FillColor '#99F6E4' -FillOpacity 0.35
                PdfHeading 'Styled report'
              }

New-OfficePdf -Path .\Examples\Documents\PdfBookmarks.pdf {
                Add-OfficePdfText -Run @(
                  @{ Text = 'Jump to details'; LinkDestinationName = 'details'; Color = '#2563EB'; Underline = $true }
                )
                Add-OfficePdfPageBreak
                Add-OfficePdfBookmark -Name 'details'
                Add-OfficePdfHeading -Text 'Details' -Level 2
              }

$sales = @(
                [pscustomobject]@{ Region = 'North'; Q1 = 1.42; Q2 = 1.55; Q3 = 1.71 }
                [pscustomobject]@{ Region = 'South'; Q1 = 0.98; Q2 = 1.04; Q3 = 1.12 }
                [pscustomobject]@{ Region = 'East'; Q1 = 1.21; Q2 = 1.18; Q3 = 1.36 }
                [pscustomobject]@{ Region = 'West'; Q1 = 1.65; Q2 = 1.79; Q3 = 1.88 }
            )
            New-OfficePdf -Path .\Sales.pdf {
                PdfChart -InputObject $sales -Category Region -Value Q3 -Title 'Q3 revenue by region (USD m)'
            }

New-OfficePdf -Path .\Columns.pdf {
                PdfRow {
                    PdfColumn { PdfHeading 'Signals' -Level 2 }
                    PdfColumn { PdfPanel 'All checks passed.' }
                }
            }

New-OfficePdf -Path .\Examples\Documents\PdfHeadings.pdf {
                Add-OfficePdfHeading -Text 'Service Review' -Level 1 -Color '#1D4ED8'
                Add-OfficePdfHeading -Text 'Open risks' -Level 2
                Add-OfficePdfParagraph -Text 'Heading levels create the report structure.'
              }

New-OfficePdf -Path .\Examples\Documents\PdfDivider.pdf {
                Add-OfficePdfHeading -Text 'Executive summary'
                Add-OfficePdfParagraph -Text 'The service is healthy.'
                Add-OfficePdfHorizontalRule -Color '#CBD5E1' -Thickness 0.75 -SpacingBefore 10 -SpacingAfter 10
                Add-OfficePdfHeading -Text 'Signals' -Level 2
              }

New-OfficePdf -Path .\Actions.pdf {
                PdfList {
                    PdfListItem 'Confirm the service owner'
                    PdfListItem 'Publish the summary'
                    PdfListItem 'Schedule the review'
                }
            }

New-OfficePdf -Path .\Checklist.pdf {
                PdfList {
                    PdfListItem 'Backups verified'
                    PdfListItem 'Monitoring silenced'
                }
            }

New-OfficePdf -Path .\Examples\Documents\PdfPageBreak.pdf {
                Add-OfficePdfHeading -Text 'Service review'
                Add-OfficePdfParagraph -Text 'Summary content stays on the first page.'
                Add-OfficePdfPageBreak
                Add-OfficePdfHeading -Text 'Appendix' -Level 2
            }

New-OfficePdf -Path .\Numbered.pdf {
                PdfFooter {
                    PdfText 'Page '
                    PdfPageNumber -IncludeTotal
                }
                PdfParagraph 'Body text.'
            }

New-OfficePdf -Path .\Examples\Documents\PdfPanel.pdf {
                Add-OfficePdfHeading -Text 'Executive summary'
                Add-OfficePdfPanel -Text 'No critical incidents were detected in the current reporting window.' -Alignment Center
            }

New-OfficePdf -Path .\TwoColumns.pdf {
                PdfRow {
                    PdfColumn { PdfParagraph 'Left column' }
                    PdfColumn { PdfParagraph 'Right column' }
                }
            }

New-OfficePdf -Path .\Examples\Documents\PdfSpacer.pdf {
                Add-OfficePdfHeading -Text 'Summary'
                Add-OfficePdfParagraph -Text 'First block.'
                Add-OfficePdfSpacer -Height 18
                Add-OfficePdfParagraph -Text 'Second block after additional spacing.'
            }

$services = @(
                [pscustomobject]@{ Name = 'Directory'; Status = 'Healthy'; Incidents = 0 }
                [pscustomobject]@{ Name = 'Mail'; Status = 'Watch'; Incidents = 2 }
            )
            New-OfficePdf -Path .\Examples\Documents\PdfTable.pdf {
                Add-OfficePdfHeading -Text 'Service status'
                Add-OfficePdfTable -InputObject $services -Property Name,Status,Incidents -Header 'Service','Status','Incidents'
            }

New-OfficePdf -Path .\Examples\Documents\PdfWatermark.pdf {
                Add-OfficePdfWatermark -Text 'DRAFT' -Size 72 -Opacity 0.12 -Rotation -35 -Color '#64748B'
                Add-OfficePdfHeading -Text 'Draft service review'
                Add-OfficePdfParagraph -Text 'This copy is not final.'
            }

$rows = @(
                [pscustomobject]@{ Month = 'Jan'; Sales = 42; Profit = 9 }
                [pscustomobject]@{ Month = 'Feb'; Sales = 55; Profit = 13 }
            )
            New-OfficePowerPoint -Path .\Examples\Documents\PowerPointChart.pptx {
                $slide = Add-OfficePowerPointSlide -PassThru
                Add-OfficePowerPointChart -Slide $slide -InputObject $rows -Category Month -Value Sales,Profit -Title 'Monthly performance'
            }

$rows = @(
                [pscustomobject]@{ Quarter = 1; Revenue = 20 }
                [pscustomobject]@{ Quarter = 2; Revenue = 34 }
            )
            New-OfficePowerPoint -Path .\Examples\Documents\PowerPointScatter.pptx {
                $slide = Add-OfficePowerPointSlide -PassThru
                Add-OfficePowerPointChart -Slide $slide -Type Scatter -InputObject $rows -Category Quarter -Value Revenue -Title 'Revenue trend'
            }

New-OfficePowerPoint -Path ./Review.pptx {
                PowerPointFooter 'Contoso | Confidential'
                PowerPointFooter -Alignment Right { PowerPointSlideNumber -IncludeTotal }
                PowerPointSlide -Title 'Service review'
            }

PowerPointSlide -Title 'Status' {
                $paragraph = PowerPointParagraph { PowerPointText 'Healthy' -Bold } -PassThru
                $paragraph.AddText(' in all regions')
            }

New-OfficePowerPoint -Path ./Results.pptx {
                PowerPointSection 'Results'
                PowerPointSlide -Title 'Revenue' { PowerPointParagraph 'Revenue increased.' }
                PowerPointSlide -Title 'Margin' { PowerPointParagraph 'Margin improved.' }
            }

New-OfficePowerPoint -Path .\Review.pptx {
                PowerPointSlide -Title 'Service review' -Subtitle 'October 2026'
                PowerPointSlide -Title 'Signals' { PowerPointCard 'Availability' -Text 'All regions healthy' }
            }

$shape = Get-OfficePowerPointShape -Document $ppt -Text 'Metric' -Kind Table | Select-Object -First 1
            $shape | Add-OfficePowerPointTableRow -Position 2 -TemplateRow 2 -Value ([ordered]@{
                Metric = 'Documentation'
                State  = 'Ready'
            })

PowerPointSlide -Title 'Service review' {
                PowerPointTextBox -X 2cm -Y 4cm -Width 12cm -Height 3cm {
                    PowerPointParagraph { PowerPointText 'Status: ' -Bold; PowerPointText 'Healthy' }
                }
            }

OfficeVisio -Path .\Flow.vsdx {
                VisioRectangle -Key source -Text 'Source' -X 1 -Y 4
                VisioRectangle -Key target -Text 'Target' -X 4 -Y 4
                VisioConnector -From source -To target -Kind RightAngle -EndArrow Triangle -Label 'sync'
            }

OfficeVisio -Path .\Architecture.vsdx {
                VisioRectangle -Key api -Text 'API' -X 2 -Y 4
                VisioRectangle -Key worker -Text 'Worker' -X 4 -Y 4
                VisioContainer -Key app -Text 'Application tier' -ShapeId api,worker -FillColor '#F8FAFC'
            }

OfficeVisio -Path .\StencilFlow.vsdx -UseMastersByDefault {
                VisioStencilImport -BuiltIn Flowchart -Name Flow -Default
                VisioStencil -Catalog Flow -Stencil process -Key intake -Text 'Intake' -X 1.5 -Y 4
            }

$rows = @(
                [pscustomobject]@{ Region = 'North America'; Revenue = 125000; Profit = 42000 }
                [pscustomobject]@{ Region = 'EMEA'; Revenue = 98000; Profit = 31000 }
                [pscustomobject]@{ Region = 'APAC'; Revenue = 143000; Profit = 52000 }
            )
            New-OfficeWord -Path .\RegionalReport.docx {
                Add-OfficeWordParagraph -Text 'Regional revenue'
                Add-OfficeWordChart -Type Pie -InputObject $rows -Category Region -Value Revenue -Title 'Revenue mix' -FitToPageWidth -WidthFraction 0.75
                Add-OfficeWordChart -Type Bar -InputObject $rows -Category Region -Value Revenue, Profit -Legend -XAxisTitle 'Region' -YAxisTitle 'Amount'
